from pwn import *
import os

ZONE = '/home/ctfplayer/ctf_files/zone'

context.binary = ZONE
context.terminal = ['tmux', 'splitw', '-h']

def run_and_print(inputs_list, description):
    print(f'----- {description} -----')
    io = process(ZONE)
    try:
        for entry in inputs_list:
            if entry['wait_line']:
                out = io.recvline(timeout=3)
                print(f'> {out.decode(errors="replace").rstrip()}')
            if entry['send'] is not None:
                print(f'< {entry["send"][0:40]!r}...')
                io.sendline(entry['send'])
        # Drain any more output
        while not io.closed:
            try:
                out = io.recvline(timeout=1)
                if out: print(f'> {out.decode(errors="replace").rstrip()}')
            except EOFError:
                break
    except Exception as e:
        print(f'[!!] Exception: {e}')
    finally:
        io.close()
    print()

def main():
    # Try no input, just run the binary
    run_and_print([], 'No input at all')

    # Try a short word
    run_and_print([
        {'wait_line':True, 'send':b'hi'},
    ], 'Short input')

    # Overly long input (200 A's)
    run_and_print([
        {'wait_line':True, 'send':b'A'*200},
    ], 'Overly long input')

    # Format string input
    run_and_print([
        {'wait_line':True, 'send':b'%x%x%x%x'},
    ], 'Format string input')

    # Large number as input
    run_and_print([
        {'wait_line':True, 'send':b'999999999'},
    ], 'Large number input')
    # Negative number
    run_and_print([
        {'wait_line':True, 'send':b'-1337'},
    ], 'Negative number input')

if __name__ == '__main__':
    main()

from pwn import *
import os

ZONE = '/home/ctfplayer/ctf_files/zone'

context.binary = ZONE
context.terminal = ['tmux', 'splitw', '-h']

def run_and_print(inputs_list, description):
    print(f'----- {description} -----')
    io = process(ZONE)
    try:
        for entry in inputs_list:
            if entry['wait_line']:
                out = io.recvline(timeout=3)
                print(f'> {out.decode(errors="replace").rstrip()}')
            if entry['send'] is not None:
                print(f'< {entry["send"][0:40]!r}...')
                io.sendline(entry['send'])
        # Drain any more output
        for _ in range(8):
            try:
                out = io.recvline(timeout=1)
                if out: print(f'> {out.decode(errors="replace").rstrip()}')
            except EOFError:
                break
    except Exception as e:
        print(f'[!!] Exception: {e}')
    finally:
        io.close()
    print()

def main():
    # Try no input, just run the binary
    run_and_print([], 'No input at all')

    # Try a short word
    run_and_print([
        {'wait_line':True, 'send':b'hi'},
    ], 'Short input')

    # Overly long input (200 A's)
    run_and_print([
        {'wait_line':True, 'send':b'A'*200},
    ], 'Overly long input')

    # Format string input
    run_and_print([
        {'wait_line':True, 'send':b'%x%x%x%x'},
    ], 'Format string input')

    # Large number as input
    run_and_print([
        {'wait_line':True, 'send':b'999999999'},
    ], 'Large number input')
    # Negative number
    run_and_print([
        {'wait_line':True, 'send':b'-1337'},
    ], 'Negative number input')

if __name__ == '__main__':
    main()

